/* From Uiverse.io by gharsh11032000 - Tags: radio, radio-buttons, click effect */
.__UIV_SCOPE__ .radio-button-container {
  display: flex;
  align-items: center;
  gap: 24px;
}

.__UIV_SCOPE__ .radio-button {
  display: inline-block;
  position: relative;
  cursor: pointer;
}

.__UIV_SCOPE__ .radio-button__input {
  position: absolute;
  opacity: 0;
  width: 0;
  height: 0;
}

.__UIV_SCOPE__ .radio-button__label {
  display: inline-block;
  padding-left: 30px;
  margin-bottom: 10px;
  position: relative;
  font-size: 15px;
  color: #f2f2f2;
  font-weight: 600;
  cursor: pointer;
  text-transform: uppercase;
  transition: all 0.3s ease;
}

.__UIV_SCOPE__ .radio-button__custom {
  position: absolute;
  top: 0;
  left: 0;
  width: 20px;
  height: 20px;
  border-radius: 50%;
  border: 2px solid #555;
  transition: all 0.3s ease;
}

.__UIV_SCOPE__ .radio-button__input:checked + .radio-button__label .radio-button__custom {
  background-color: #4c8bf5;
  border-color: transparent;
  transform: scale(0.8);
  box-shadow: 0 0 20px #4c8bf580;
}

.__UIV_SCOPE__ .radio-button__input:checked + .radio-button__label {
  color: #4c8bf5;
}

.__UIV_SCOPE__ .radio-button__label:hover .radio-button__custom {
  transform: scale(1.2);
  border-color: #4c8bf5;
  box-shadow: 0 0 20px #4c8bf580;
}
